INSERT INTO `offers` (`id`, `title`, `short_description`, `detailed_description`, `offer_type`, `starting_price`, `starting_price_usd`, `discount_price`, `discount_price_usd`, `valid_from`, `valid_till`, `status`, `is_featured`, `button_text`, `button_action`, `button_url`, `display_order`, `banner_image_url`, `seo_title`, `seo_description`, `created_by`, `updated_by`, `created_at`, `updated_at`, `slug`, `billing_period`, `setup_fee`, `setup_fee_usd`, `booking_amount_type`, `booking_amount`, `booking_amount_usd`, `target_audience`, `whats_included`, `whats_not_included`, `update_policy`, `ownership_policy`, `terms`, `target_keywords`) VALUES ('8b4ef3e1-7d0b-45a5-8bf6-4b2c036b4130', 'High-Converting Business Website', 'A high-speed, modern, lead-generating corporate website engineered to establish instant brand authority, rank on Google, and convert inbound visitors into high-value clients.', 'Most business websites look decent but fail to generate actual revenue. Our Business Website package bridges the gap between high-end aesthetic design and aggressive conversion engineering.\n\nWe build up to 5 custom-crafted, lightning-fast pages tailored specifically to your industry—featuring mobile-first responsive architecture, trust badges, customer proof showcases, and friction-free inquiry capture funnels. Whether you are scaling an agency, consultancy, B2B service, or professional practice, this package positions your brand as the undisputed market leader while Google\'s search algorithms reward your sub-1.5s Core Web Vitals performance.', 'Website Presence', 25999, 499, 8999, 199, NULL, NULL, 'Active', 1, 'Book Your Website Slot', 'Contact Form', NULL, 2, NULL, 'High-Converting Business Website Design | Techneyo Solutions', 'Launch a fast, modern corporate website built to rank on Google and convert visitors into clients. Up to 5 pages, WhatsApp lead capture & SEO architecture.', NULL, 'a2644ba4-20f4-45f1-8cee-a0ed1f11ae4a', '2026-07-15T09:02:47.802706+00:00', '2026-07-23T18:04:05.930585+00:00', 'business-website', 'monthly', NULL, NULL, 'fixed', 999, 29, '[\"Growing B2B Teams & Service Agencies\", \"Consultants, Advisors & Professional Firms\", \"Local Business Owners Ready to Scale Digitally\", \"Founders Launching a Premium Corporate Brand\", \"Companies Upgrading Outdated, Slow Legacy Websites\"]', '[\"Up to 5 Custom-Designed Responsive Pages (Home, About Us, Services/Solutions, Case Studies/Portfolio, Contact)\", \"Frictionless Inbound Lead Funnel with Smart Contact Forms & Instant Email/WhatsApp Lead Notifications\", \"Sub-1.5s Ultra-Fast Load Speeds with 95+ Core Web Vitals Optimization (Mobile & Desktop)\", \"Full Technical & On-Page SEO Architecture: Clean Semantic HTML5, Schema.org Markup, XML Sitemap & OpenGraph Tags\", \"1-Click WhatsApp Floating Chat Widget for Immediate Inbound Inquiry Capture\", \"Trust & Conversion Sections: Client Testimonials, Certification Badges, Interactive FAQs, & Clear CTAs\", \"Google Analytics 4 (GA4) & Google Search Console Verification & Conversion Event Tracking\", \"Enterprise SSL Security, Modern Cloud Hosting CDN Setup, & Daily Automated Uptime Monitoring\", \"Mobile-First Adaptive Design tested across iOS, Android, macOS, and Windows browsers\", \"Easy Content Management Handover with full admin walkthrough and training\"]', '[\"Custom complex SaaS web applications, portal logic, or multi-vendor marketplace engines (Available via Custom Tool)\", \"Paid advertising budget / ad spend for Google Search Ads or Meta Campaigns\", \"Professional on-location photography or custom video shoot production\", \"Complex third-party custom ERP / legacy mainframe backend database integrations\", \"Ongoing content writing beyond the initial 5-page copywriting polish and keyword alignment\"]', 'Every website includes 30 days of complimentary hyper-care support post-launch. For ongoing care, your subscription covers continuous cloud server uptime, enterprise SSL renewals, core security updates, daily backups, and up to 2 hours of monthly content updates (updating copy, images, team members, or service offerings). Additional custom development is available anytime at discounted member hourly rates.', '100% Client Ownership Guarantee: You retain complete and total ownership of your domain, brand assets, copywriting, customer data, and graphics. No vendor lock-in. Full production source code exports and deployment handover files are provided upon request, allowing you to self-host or transfer anywhere whenever you choose.', '[\"Advance booking of Rs. 999 (India) / $29 (Global) confirms your onboarding slot and schedules the technical discovery call.\", \"Fast Turnaround: Initial functional staging preview delivered within 7 to 10 business days of asset handover.\", \"Includes 2 comprehensive rounds of structured design and content revisions before production sign-off.\", \"Post-launch 30-day bug-fix guarantee and priority technical support included.\"]', '[\"business website design\", \"corporate website development\", \"lead generation business website\", \"b2b web design company\", \"custom website design india\", \"professional service website\", \"high converting business website\", \"techneyo business website\"]') ON DUPLICATE KEY UPDATE `updated_at` = CURRENT_TIMESTAMP;
